import React from "react";
import "./../../css/Profile.css";

class Profile extends React.Component {
  state = {
    user: null,
    loading: true,
    error: "",

    toggles: {
      appointment: true,
      sms: true,
      email: false,
      marketing: false,
    },
  };

  componentDidMount() {
    this.getProfile();
  }

  getProfile = () => {
    fetch("http://127.0.0.1:8000/api/profile")
      .then((response) => {
        if (!response.ok) {
          throw new Error("خطا در دریافت اطلاعات پروفایل");
        }

        return response.json();
      })
      .then((result) => {
        console.log("Profile API:", result);

        this.setState({
          user: result.data?.user || null,
          loading: false,
          error: "",
        });
      })
      .catch((error) => {
        console.error("Profile API Error:", error);

        this.setState({
          error: "دریافت اطلاعات پروفایل با خطا مواجه شد.",
          loading: false,
        });
      });
  };

  handleToggle = (name) => {
    this.setState((prevState) => ({
      toggles: {
        ...prevState.toggles,
        [name]: !prevState.toggles[name],
      },
    }));
  };

  renderToggle = (name, label) => {
    return (
      <button
        type="button"
        className={`toggle ${this.state.toggles[name] ? "on" : ""}`}
        onClick={() => this.handleToggle(name)}
        aria-label={label}
      >
        <span className="toggle-knob"></span>
      </button>
    );
  };

  formatPhone = (phone) => {
    if (!phone) {
      return "-";
    }

    const value = String(phone);

    if (value.length === 11) {
      return `${value.substring(0, 4)} ${value.substring(
        4,
        7
      )} ${value.substring(7)}`;
    }

    return value;
  };

  formatValue = (value) => {
    if (
      value === null ||
      value === undefined ||
      value === ""
    ) {
      return "-";
    }

    return value;
  };

  formatGender = (gender) => {
    if (!gender) {
      return "-";
    }

    if (gender === "male") {
      return "مرد";
    }

    if (gender === "female") {
      return "زن";
    }

    return gender;
  };

  formatStatus = (status) => {
    if (!status) {
      return "عضو";
    }

    if (status === "active") {
      return "عضو فعال";
    }

    if (status === "inactive") {
      return "غیرفعال";
    }

    if (status === "blocked") {
      return "مسدود";
    }

    return status;
  };

  formatObject = (value) => {
    if (
      value === null ||
      value === undefined ||
      value === ""
    ) {
      return "-";
    }

    if (typeof value === "object") {
      return JSON.stringify(value);
    }

    return String(value);
  };

  getFullName = () => {
    const { user } = this.state;

    if (!user) {
      return "کاربر";
    }

    const firstName = user.first_name || "";
    const lastName = user.last_name || "";

    const fullName = `${firstName} ${lastName}`.trim();

    return fullName || "کاربر";
  };

  getAvatarText = () => {
    const fullName = this.getFullName();

    const words = fullName
      .split(" ")
      .filter((item) => item.trim());

    if (words.length >= 2) {
      return `${words[0].charAt(0)}${words[1].charAt(0)}`;
    }

    return words[0]?.charAt(0) || "ک";
  };

  render() {
    const {
      user,
      loading,
      error,
    } = this.state;

    if (loading) {
      return (
        <div className="scroll-area">
          <div
            style={{
              textAlign: "center",
              padding: "50px 20px",
            }}
          >
            در حال دریافت اطلاعات پروفایل...
          </div>
        </div>
      );
    }

    if (error) {
      return (
        <div className="scroll-area">
          <div
            style={{
              textAlign: "center",
              padding: "50px 20px",
            }}
          >
            {error}
          </div>
        </div>
      );
    }

    if (!user) {
      return (
        <div className="scroll-area">
          <div
            style={{
              textAlign: "center",
              padding: "50px 20px",
            }}
          >
            اطلاعات کاربر پیدا نشد.
          </div>
        </div>
      );
    }

    const fullName = this.getFullName();

    const phone = user.phone || "";
    const email = user.email || "";
    const nationalCode = user.national_code || "";
    const birthDate = user.birth_date || "";
    const gender = user.gender || "";
    const avatar = user.avatar || "";

    const address = user.address || "";
    const postalCode = user.postal_code || "";

    const status = user.status || "";
    const lastLoginAt = user.last_login_at || "";

    const referralCode = user.referral_code || "";
    const referredBy = user.referred_by || "";

    const skinInfo = user.skin_info || "";
    const hairInfo = user.hair_info || "";
    const healthInfo = user.health_info || "";
    const medicalNotes = user.medical_notes || "";

    const experience = user.experience || "";
    const about = user.about || "";
    const source = user.source || "";
    const tags = user.tags || "";

    const points =
      user.points !== null &&
      user.points !== undefined
        ? user.points
        : 0;

    const tierId = user.tier_id || "";

    const createdAt = user.created_at || "";
    const updatedAt = user.updated_at || "";

    const clinic =
      user.clinic ||
      user.clinic_name ||
      "اوراکلینیک — شعبه مرکزی";

    const specialist =
      user.specialist ||
      user.specialist_name ||
      user.doctor ||
      user.doctor_name ||
      "دکتر آناهیتا کریمی";

    return (
      <>
        <div className="page-header">
          <button
            className="icon-btn"
            aria-label="بازگشت"
            onClick={() => window.history.back()}
            type="button"
          >
            <svg
              width="18"
              height="18"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="m9 18 6-6-6-6" />
            </svg>
          </button>

          <div className="page-title">
            پروفایل من
          </div>

          <button
            className="icon-btn"
            aria-label="تنظیمات"
            type="button"
          >
            <svg
              width="18"
              height="18"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <circle cx="12" cy="12" r="3" />

